<?php
require dirname(__DIR__).'/bootstrap.php';requireRole('admin');$pageTitle='Reports';$dashboardMode=true;$pdo=Database::connection();
$classRows=$pdo->query('SELECT c.id,c.class_name,c.section,(SELECT COUNT(*) FROM class_students cs WHERE cs.class_id=c.id) students,(SELECT COUNT(*) FROM exams e WHERE e.class_id=c.id) exams,(SELECT COUNT(*) FROM exam_attempts a JOIN exams e2 ON e2.id=a.exam_id WHERE e2.class_id=c.id) attempts,(SELECT ROUND(AVG(a.obtained_marks),2) FROM exam_attempts a JOIN exams e3 ON e3.id=a.exam_id WHERE e3.class_id=c.id AND a.status="evaluated") average_score FROM classes c ORDER BY c.class_name')->fetchAll();
$activity=$pdo->query('SELECT al.*,u.name FROM audit_logs al LEFT JOIN users u ON u.id=al.user_id ORDER BY al.created_at DESC LIMIT 30')->fetchAll();$totalAttempts=(new Database())->count('exam_attempts');$evaluated=(new Database())->count('exam_attempts',['status'=>'evaluated']);$pass=$pdo->query('SELECT COUNT(*) FROM exam_attempts a JOIN exams e ON e.id=a.exam_id WHERE a.status="evaluated" AND a.obtained_marks>=e.passing_marks AND (e.result_publish_at IS NULL OR e.result_publish_at<=NOW())')->fetchColumn();$published=$pdo->query('SELECT COUNT(*) FROM exams WHERE status="published" AND (result_publish_at IS NULL OR result_publish_at<=NOW())')->fetchColumn();
require APP_ROOT.'/components/header.php';
?>
<div class="page-heading"><div><h1>Reports</h1><p>Participation and performance across classes.</p></div><span class="badge badge-blue">Updated <?= date('M j, Y') ?></span></div>
<section class="dashboard-grid"><article class="metric-card"><span class="metric-icon">▣</span><div class="metric-copy"><strong><?= number_format($totalAttempts) ?></strong><span>Total attempts</span></div></article><article class="metric-card"><span class="metric-icon teal">✓</span><div class="metric-copy"><strong><?= number_format($evaluated) ?></strong><span>Evaluated attempts</span></div></article><article class="metric-card"><span class="metric-icon purple">◉</span><div class="metric-copy"><strong><?= number_format((int)$published) ?></strong><span>Published exams</span></div></article><article class="metric-card"><span class="metric-icon amber"><?= $evaluated?round($pass/$evaluated*100):0 ?>%</span><div class="metric-copy"><strong><?= $evaluated?round($pass/$evaluated*100):0 ?>%</strong><span>Pass rate</span></div></article></section>
<section class="panel"><div class="panel-header"><h2>Class performance</h2></div><div class="panel-body flush"><div class="table-wrap"><table><thead><tr><th>Class</th><th>Students</th><th>Exams</th><th>Attempts</th><th>Average score</th></tr></thead><tbody><?php foreach($classRows as $row): ?><tr><td><strong><?= e($row['class_name']) ?><?= $row['section']?' · '.e($row['section']):'' ?></strong></td><td><?= (int)$row['students'] ?></td><td><?= (int)$row['exams'] ?></td><td><?= (int)$row['attempts'] ?></td><td><?= $row['average_score']===null?'—':e(money($row['average_score'])) ?></td></tr><?php endforeach; ?><?php if(!$classRows): ?><tr><td colspan="5"><div class="empty-state">No class reporting data yet.</div></td></tr><?php endif; ?></tbody></table></div></div></section>
<section class="panel" id="activity"><div class="panel-header"><h2>Audit activity</h2></div><div class="panel-body flush"><div class="table-wrap"><table><thead><tr><th>Action</th><th>User</th><th>Entity</th><th>When</th></tr></thead><tbody><?php foreach($activity as $item): ?><tr><td><?= e(ucwords(str_replace('_',' ',$item['action']))) ?></td><td><?= e($item['name']??'System') ?></td><td><?= e($item['entity_type']??'—') ?><?= $item['entity_id']?' #'.(int)$item['entity_id']:'' ?></td><td><?= dateTime($item['created_at']) ?></td></tr><?php endforeach; ?><?php if(!$activity): ?><tr><td colspan="4"><div class="empty-state">Audit activity will appear here.</div></td></tr><?php endif; ?></tbody></table></div></div></section>
<?php require APP_ROOT.'/components/footer.php'; ?>
